/* A loop that reads two values made before it on every trip (case 70). */
static const char gl_test_loopcarry_fs_src[] =
	"/* A loop that reads, on every trip, two values made before it: the bound `n`\n"
	" * and the addend `k`, then makes a value of its own (`t`). The online\n"
	" * allocator ended both ranges at their last mention inside the body and gave\n"
	" * `t` their register, so from the second trip the test and the sum read `t`.\n"
	" * With u_k = (1, 0.25): n = 3, three trips, red = 3 * 0.25 = 0.75. */\n"
	"precision mediump float;\n"
	"uniform vec4 u_k;\n"
	"void main()\n"
	"{\n"
	"	float n = ceil(u_k.x * 3.0);\n"
	"	float k = u_k.y;\n"
	"	float acc = 0.0;\n"
	"	for (float i = 0.0; i < 8.0; i += 1.0) {\n"
	"		if (i >= n) {\n"
	"			break;\n"
	"		}\n"
	"		acc += k;\n"
	"		float t = acc * 2.0;\n"
	"		acc = t * 0.5;\n"
	"	}\n"
	"	gl_FragColor = vec4(acc, 0.0, 0.0, 1.0);\n"
	"}\n";

/* Dead work before a loop and inside it; deleting it renumbers the
 * branches (case 71). */
static const char gl_test_deadloop_fs_src[] =
	"/* Work nobody reads, before a loop and inside it, around a loop that must\n"
	" * still run its three trips. `unused` is an if with an early return (joined\n"
	" * by selects, the shape femtovg's scissorMask takes when the variant does not\n"
	" * use it) and `waste` is carried round the loop and never read after it. The\n"
	" * online back end deletes both, which renumbers every instruction after them:\n"
	" * the break's target, the back edge's target and the back-edge list the ABI\n"
	" * checks. With u_k = (1, 0.25, 1, 0): red = 3 * 0.25 = 0.75. */\n"
	"precision mediump float;\n"
	"uniform vec4 u_k;\n"
	"float unused(vec2 p)\n"
	"{\n"
	"	if (u_k.z > 0.0) {\n"
	"		return p.x * 2.0 + p.y;\n"
	"	}\n"
	"	return p.y * 3.0;\n"
	"}\n"
	"void main()\n"
	"{\n"
	"	float dead = unused(u_k.xy);\n"
	"	float n = ceil(u_k.x * 3.0);\n"
	"	float acc = 0.0;\n"
	"	float waste = 0.0;\n"
	"	for (float i = 0.0; i < 8.0; i += 1.0) {\n"
	"		if (i >= n) {\n"
	"			break;\n"
	"		}\n"
	"		waste = waste * 3.0 + i;\n"
	"		acc += u_k.y;\n"
	"	}\n"
	"	gl_FragColor = vec4(acc, 0.0, 0.0, 1.0);\n"
	"}\n";

