/* Two discards behind tests of lanes y and w of a varying, so each
 * quadrant of the quad takes its own branches (case 81). */
static const char gl_test_branchquad_fs_src[] =
	"/* Two discards behind tests of lanes y and w of a VARYING, so the condition\n"
	" * differs from pixel to pixel. Case 73 took its conditions from a uniform:\n"
	" * every pixel took the same branch, and on silicon it could not tell a\n"
	" * branch that read the right lane from one that did not.\n"
	" *\n"
	" * Case 81 draws v_color = (1 - t, t, 1 - s, s), s the horizontal position\n"
	" * and t the vertical one, both 0..1 across the quad. The y test discards the\n"
	" * top half and the w test the right half, so only the bottom-left quadrant is\n"
	" * green. A test that reads lane x instead of y discards the bottom half; one\n"
	" * that reads z instead of w discards the left half: every mistake moves the\n"
	" * green quadrant. */\n"
	"precision mediump float;\n"
	"varying vec4 v_color;\n"
	"void main()\n"
	"{\n"
	"	if (v_color.y > 0.5) {\n"
	"		discard;\n"
	"	}\n"
	"	vec4 col = vec4(0.0, 1.0, 0.0, 1.0);\n"
	"	if (v_color.w > 0.5) {\n"
	"		discard;\n"
	"	}\n"
	"	gl_FragColor = col;\n"
	"}\n";

/* A loop whose break point differs from pixel to pixel, and a continue
 * taken in half of them (case 87). */
static const char gl_test_databreak_fs_src[] =
	"/* A loop whose break point differs from pixel to pixel, and a continue taken\n"
	" * in half of them (case 87). The online PowerVR path keeps a loop like this\n"
	" * as ONE loop: its body once, every exit a flag, and a backward branch on a\n"
	" * counter that is the same in every instance. The instances therefore\n"
	" * disagree about where their loop stops while they all take the branch\n"
	" * together, and this is the case that shows the flags doing that job.\n"
	" *\n"
	" * Case 87 draws v_color = (1 - t, t, 1 - s, s), s the horizontal position and\n"
	" * t the vertical one, both 0..1 across the quad. The loop counts iterations\n"
	" * until i reaches s * 8, so band b of eight (left to right) counts b + 1;\n"
	" * above the middle it skips iteration 2, so from band 2 up it counts one\n"
	" * fewer. Red is the count over 8; blue says which half the pixel is in. */\n"
	"precision highp float;\n"
	"varying vec4 v_color;\n"
	"void main()\n"
	"{\n"
	"	float s = v_color.w;\n"
	"	float top = v_color.y;\n"
	"	float count = 0.0;\n"
	"	for (int i = 0; i < 8; i++) {\n"
	"		if (float(i) >= s * 8.0) {\n"
	"			break;\n"
	"		}\n"
	"		if (top > 0.5 && i == 2) {\n"
	"			continue;\n"
	"		}\n"
	"		count += 1.0;\n"
	"	}\n"
	"	gl_FragColor = vec4(count / 8.0, 0.0, top > 0.5 ? 1.0 : 0.0, 1.0);\n"
	"}\n";

