/* Integer division on both signs and in vector lanes (case 79). */
static const char gl_test_idiv_fs_src[] =
	"/* Integer division, truncated toward zero, on both signs and in every lane\n"
	" * of a vector: the online compiler refused it (Lower(Unsupported(Idiv)),\n"
	" * 148 dEQP case-sides). Divisors are kept at 1 or more so any input is\n"
	" * defined. With u_d = (0.7, -0.7, 1.0, 1.0): n = (7, -7), d = (2, 3),\n"
	" * n / d = (3, -2), and 100 / (|7| + 1) = 12; the colour is\n"
	" * (3 / 4, (-2 + 4) / 4, 12 / 16, 1) = (0.75, 0.5, 0.75, 1.0). gl_test case 79. */\n"
	"precision mediump float;\n"
	"uniform vec4 u_d;\n"
	"void main()\n"
	"{\n"
	"	ivec2 n = ivec2(int(u_d.x * 10.0), int(u_d.y * 10.0));\n"
	"	ivec2 d = ivec2(int(abs(u_d.z)) + 1, int(abs(u_d.w)) + 2);\n"
	"	ivec2 q = n / d;\n"
	"	int big = 100 / (int(abs(u_d.x * 10.0)) + 1);\n"
	"	gl_FragColor = vec4(float(q.x) / 4.0, float(q.y + 4) / 4.0, float(big) / 16.0, 1.0);\n"
	"}\n";

/* sin, cos, log2 and exp2 at exact arguments (case 77). */
static const char gl_test_transc_fs_src[] =
	"/* The transcendentals, one lane each, at arguments whose results are exact\n"
	" * in eight bits: with u_a = (pi/6, pi/3, 2.0, -1.0) the colour is\n"
	" * (sin, cos, log2 / 4, exp2) = (0.5, 0.5, 0.25, 0.5). On this core sin and\n"
	" * cos take their argument in units of pi, and sin, cos and log write a pair\n"
	" * of lanes whose product is the result (Mesa's etna_lower_alu); a plain\n"
	" * `sin` of radians computes something else. gl_test case 77. */\n"
	"precision mediump float;\n"
	"uniform vec4 u_a;\n"
	"void main()\n"
	"{\n"
	"	gl_FragColor = vec4(sin(u_a.x), cos(u_a.y), log2(u_a.z) * 0.25, exp2(u_a.w));\n"
	"}\n";

/* Scalar operations applied to vectors (case 77). */
static const char gl_test_vtransc_fs_src[] =
	"/* Scalar operations applied to vectors. One scalar instruction computes one\n"
	" * lane, so `sin(v)` emitted once was sin(v.x) in every lane. With\n"
	" * u_v = (pi/6, pi/2, 0.0, 4.0): sin of the first three is (0.5, 1.0, 0.0),\n"
	" * and the SECOND lane of inversesqrt(vec2(1.0, 4.0)) is 0.5 -- a broadcast\n"
	" * of the first lane would give 1.0 there. gl_test case 77. */\n"
	"precision mediump float;\n"
	"uniform vec4 u_v;\n"
	"void main()\n"
	"{\n"
	"	vec3 s = sin(u_v.xyz);\n"
	"	vec2 r = inversesqrt(vec2(1.0, u_v.w));\n"
	"	gl_FragColor = vec4(s, r.y);\n"
	"}\n";

